      "same": true,
      "reason": "Both describe the issue as a lack of integration between transaction behaviors and contract semantics in existing PMA detection methods, leading to reliability issues."
    },
    "chk_method": {
      "same": true,
      "reason": "Both describe DeFiFusion as a dual-modal PMA detection framework using transaction events, smart contract semantics, a DPF-Transformer, and T5-style relative positional encoding."
    },
    "chk_data": {
      "same": true,
      "reason": "Both describe datasets with 225 real-world PMA incidents and 1,150 benign transactions from 435 DeFi applications, though A provides more detail about the networks and time range."
    },
    "chk_setup": {
      "same": false,
      "reason": "A describes the implementation details like batch size, dropout rate, and learning rate, while B focuses on evaluation setup with cross-validation and dataset usage."
    },
    "chk_primary_result": {
      "same": false,
      "reason": "A states 96.10% precision and recalls 222 out of 225 PMA cases, while B states 96.10% precision, 98.67% recall, and 100% recall on 18 real-world 2026 PMA incidents."
    },
    "chk_secondary_result": {
      "same": false,
      "reason": "A highlights 100% recall on 18 real-world 2026 PMA incidents, while B emphasizes outperforming state-of-the-art methods in detecting PMAs, including high-value attacks."
    },
    "chk_baseline": {
      "same": false,
      "reason": "A lists three tools (DeFiRanger, DeFort, and DeFiScope), while B adds two more tools (DeFiTainter and SMARTCAT)."
    },
    "chk_conclusion": {
      "same": true,
      "reason": "Both conclude that DeFiFusion achieves state-of-the-art performance by integrating transaction events and smart contract semantics."
    },
    "chk_limitation": {
      "same": true,
      "reason": "Both describe the limitation as the model's dependence on source code, which affects detection for unverified or closed-source contracts."
    }
  }
